import sys; sys.path.insert(0,"/workspace/social/posts"); from build10 import build
B=r'''<style>.box p,.box li{font-size:20px;line-height:1.27}.box h2{font-size:26px;margin-bottom:5px}.tbl{font-size:18px}.note,.warn{font-size:17px}.tbl th,.tbl td{padding:3px 6px}.iq ol{font-size:19px;line-height:1.27}.pill{font-size:16px}.grid{gap:12px}.handle{bottom:-12px}.box{padding:10px 12px}.tagline{font-size:19px;margin-bottom:9px}</style>
<div class="title">📁 HxGN EAM Case Management <span class="badge">CHEAT SHEET</span></div>
<div class="tagline">Record events that are not work orders (accidents, spills, emissions, shift notes, line stops) and drive them to closure with tasks, follow-up WOs and root cause analysis. (HxGN EAM 12.1.1 brief)</div>
<div class="grid">
<div class="box c1"><h2>1. Why a Case?</h2><ul><li>Event ≠ repair job, or WO need not clear yet</li><li>Many steps: OSHA, lawyers, inspections</li><li>Years later: proof corrective action was taken</li><li>Create manually, from <b>Call Center</b> or from <b>Work Order</b></li></ul></div>
<div class="box c2"><h2>2. Status (CXST)</h2><table class="tbl"><tr><th>Status</th><th>Effect</th></tr><tr><td><b>Requested</b></td><td>From Call Center/WO: protected until Open</td></tr><tr><td><b>Open</b></td><td>Edit data, complete tasks</td></tr><tr><td><b>Closed / Canceled</b></td><td>No field updates</td></tr></table><div class="warn">No return to Requested. Changes logged on Event Log.</div></div>
<div class="box c3"><h2>3. Type (CXTP) + template</h2><ul><li><b>*</b> = generic case, <b>RCA</b> = root cause analysis</li><li>Root Cause Analysis screen = clone of Case Mgmt</li><li><b>Service Code</b> = template: Type, Class, Priority, Regulatory, est. costs + Case Tasks</li></ul></div>
<div class="box c4"><h2>4. Tasks tab</h2><ul><li><b>Sequence</b> + <b>Step</b> (sub-sequence)</li><li>Responsible / Assigned To Role (JOBR)</li><li>Last task of a Sequence done = next <b>Ready to Start</b></li><li><b>Firm Dates</b> stop auto-moving</li><li>Task Plan for Checklist</li></ul></div>
<div class="box c5"><h2>5. Deep Dive + CASECASC</h2><ul><li>Tick <b>Deep Dive</b> + save: adds tasks from the org's Deep Dive Service Code</li><li>Untick + save removes them</li><li><b>CASECASC</b> cascades scheduled task dates; Sched. End Date then protected</li></ul></div>
<div class="box c6"><h2>6. Follow-up WO</h2><ul><li>Needs <b>Equipment</b> on the case (or task)</li><li>Standard WO, WO Type/Class/Priority, Task Plan, Trade</li><li>No WO Status = Released</li><li><b>Create Follow-up WO</b> + Refresh Cost Data</li></ul><div class="note">Equipment on case and WO is not kept in sync.</div></div>
<div class="box c7"><h2>7. RCA tools</h2><ul><li>5 Why fields + Problem / Solution</li><li><b>Root Causes</b> tab: Contribution %, category, Keep Synchronized</li><li><b>Update Work Order</b> writes closing codes, even to a closed WO</li><li><b>Fishbone</b> tab: Why 1 = primary, Why 2 = secondary</li></ul></div>
<div class="box c8"><h2>8. Links + audit</h2><ul><li>Parent case, WO, Permit to Work, Shift, Project, Campaign</li><li><b>Related Cases</b> tab, <b>Document List</b></li><li><b>Event Log</b> (ELTP), eSignatures, eRecords</li><li>Alerts: Case Task Completed / Ready To Start / Overdue Start</li></ul></div>
<div class="bottom">
<div class="box" style="border-color:#1a5f7a"><h2 style="color:#1a5f7a">9a. Improvement loop</h2><div class="flow" style="flex-wrap:wrap;row-gap:4px"><span class="pill">Equipment fails</span><span class="arr">→</span><span class="pill">WO fixes it</span><span class="arr">→</span><span class="pill">RCA case</span><span class="arr">→</span><span class="pill">Failure Modes</span><span class="arr">→</span><span class="pill">RCM tab</span></div></div>
<div class="box iq"><h2>9b. Consultant tips</h2><ol><li>Build Service Codes with Case Tasks first</li><li>Use Notify flags + Alert Management</li><li>Set Firm Dates on fixed legal deadlines</li><li>Department security applies</li></ol></div>
<div class="box" style="border-color:#2d8a5a"><h2 style="color:#2d8a5a">9c. Key points</h2><ul><li>Case ≠ WO</li><li>Service Code = template</li><li>RCA feeds RCM</li></ul></div>
</div></div>'''
build("/workspace/social/posts/2026-10-25-linkedin-eam-case-management",B,1350,"Rahul Kumar")
